     * Retrieve all <code>Owner</code>s whose last name, compared case-insensitively, equals the given name.
     *
     * @param lastName the lower-cased last name to search for
     * @return the matching owners
     */
    List<Owner> findByLastNameIgnoringCase(String lastName) throws DataAccessException;

     * Count the <code>Owner</code>s whose first and last names, compared case-insensitively, equal the given names.
     *
     * @param firstName the lower-cased first name to search for
     * @param lastName the lower-cased last name to search for
     * @return the number of matching owners
     */
    long countByFirstNameAndLastNameIgnoringCase(String firstName, String lastName) throws DataAccessException;

     * Count the <code>Owner</code>s whose city, compared case-insensitively, equals the given city.
     *
     * @param city the lower-cased city to search for
     * @return the number of matching owners
     */
    long countByCityIgnoringCase(String city) throws DataAccessException;

     * Count the <code>Owner</code>s whose registration date equals the given date.
     *
     * @param registrationDate the registration date to search for
     * @return the number of matching owners
     */
    long countByRegistrationDate(LocalDate registrationDate) throws DataAccessException;

     * Count the <code>Owner</code>s that belong to the household with the given ID.
     *
     * @param householdId the household ID to search for
     * @return the number of matching owners
     */
    long countByHouseholdId(String householdId) throws DataAccessException;

     * Count all <code>Owner</code>s in the data store.
